package catalog_test

import (
	"encoding/json"
	"os"
	"strconv"
	"strings"
	"testing"

	"github.com/toncenter/ton-indexer/ton-index-go/index/acton"
)

// The committed subset runs without Node. ACTON_REFERENCE_CORPUS can point at
// a full offline corpus generated by testdata/generate-reference.cjs --all.
func TestTSDifferential(t *testing.T) {
	path := os.Getenv("ACTON_REFERENCE_CORPUS")
	if path == "" {
		path = "testdata/ts-reference.json"
	}
	data, err := os.ReadFile(path)
	check(t, err)
	var corpus struct {
		Rows []struct {
			ID, Root, BOC string
			Deep          bool
			Value         any
		}
		Skipped map[string]int
	}
	check(t, json.Unmarshal(data, &corpus))
	passed, blocked := 0, 0
	for _, row := range corpus.Rows {
		c := contract(t, row.ID)
		var b *acton.Binding
		switch row.Root {
		case "storage":
			b = c.Storage
		case "deployment":
			b = c.DeploymentStorage
		default:
			direction, index, ok := strings.Cut(row.Root, ":")
			if !ok {
				t.Fatal(row.Root)
			}
			i, err := strconv.Atoi(index)
			check(t, err)
			b = &c.Messages[direction][i]
		}
		if b.Unsupported != "" {
			if row.ID != "bidask.BidaskRange" || !strings.Contains(b.Unsupported, "nonterminal remainder") {
				t.Fatalf("unexpected disabled reference %s %s: %s", row.ID, row.Root, b.Unsupported)
			}
			if b.Encode != nil || b.Decode != nil {
				t.Fatal("unsupported root exposed callbacks")
			}
			blocked++
			continue
		}
		t.Run(row.ID+"/"+row.Root+"/deep="+strconv.FormatBool(row.Deep), func(t *testing.T) {
			root, err := acton.DecodeBOC(row.BOC)
			check(t, err)
			got, err := b.Decode(root)
			check(t, err)
			same(t, got, row.Value)
			encoded, err := b.Encode(got)
			check(t, err)
			again, err := b.Decode(encoded)
			check(t, err)
			same(t, again, row.Value)
		})
		passed++
	}
	if blocked != 12 {
		t.Fatalf("expected both TS samples of all six unsafe Bidask roots, got %d", blocked)
	}
	if passed == 0 {
		t.Fatal("empty cross-language corpus")
	}
	t.Logf("TS vectors=%d supported=%d explicitly blocked=%d skipped by TS generator=%v", len(corpus.Rows), passed, blocked, corpus.Skipped)
}
